import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

LAST_ROW = 73
LAST_COL = 14

def is_na_error(cell):
    if cell is None:
        return False
    v = cell.value
    if v is None:
        return False
    if getattr(cell, "data_type", None) == "e":
        return str(v).strip().upper() == "#N/A"
    return isinstance(v, str) and v.strip().upper() == "#N/A"

kept_rows = []
for r in range(2, LAST_ROW + 1):
    if is_na_error(vws.cell(row=r, column=3)):
        row_values = []
        for c in range(1, LAST_COL + 1):
            v = vws.cell(row=r, column=c).value
            if isinstance(v, str):
                v = v.strip()
            row_values.append(v)
        kept_rows.append(row_values)

# Clear the full answer region first so deleted rows become empty.
for r in range(2, LAST_ROW + 1):
    for c in range(1, LAST_COL + 1):
        ws.cell(row=r, column=c).value = None

# Write kept rows starting at row 2.
for i, row_values in enumerate(kept_rows[:LAST_ROW - 1]):
    r = 2 + i
    for c, v in enumerate(row_values, start=1):
        ws.cell(row=r, column=c).value = v

wb.save(OUT)

print("kept_rows:", len(kept_rows))
if kept_rows:
    print("first kept row A:C:", kept_rows[0][:3])
